{
  "implementation": "def solve(case):
    nodes = case['nodes']
    core = case['core_distance']
    distances = case['distances']
    n = len(nodes)
    # Union-Find
    parent = {}
    rank = {}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    for v in nodes:
        parent[v] = v
        rank[v] = 0
    edges = []
    for a, b, d in distances:
        mr = max(core[a], core[b], d)
        if a < b:
            edges.append((mr, a, b))
        else:
            edges.append((mr, b, a))
    edges.sort()
    mst = []
    total = 0.0
    for mr, u, v in edges:
        if len(mst) == n - 1:
            break
        if union(u, v):
            mst.append([u, v, mr])
            total += mr
    # If disconnected, could raise, but we assume connected
    return {'mst_edges': mst, 'total_weight': total}"
}
